synonym_map = {
    "login": ["authentication", "sign in", "credentials"],
    "refund": ["reimbursement", "money back", "return"],
}

def expand_query(query, synonym_map):
    words = query.lower().split()
    expanded_terms = set(words)
    for word in words:
        if word in synonym_map:
            expanded_terms.update(synonym_map[word])
    return " ".join(expanded_terms)

original_query = "login issue"
expanded = expand_query(original_query, synonym_map)

print(f"Original query: {original_query!r}")
print(f"Expanded query: {expanded!r}")
print("\nThe expanded query carries more surface area for both sparse and dense retrieval.")
